var datum, txt, Berechnung;

// Beschreibe diese Funktion …
async function Logfile(datum, txt) {
    if (getState('0_userdata.0.Victron.DebugAktiv').val) {
      require('fs').appendFileSync('/opt/iobroker/log/' + datum + ' - victron_BAT.log', formatDate(new Date(), "hh:mm:ss") + " \t" + txt + "\n");}
}


// MODE übertragen
on({ id: [].concat(['0_userdata.0.Victron.ESS_Mode']), change: 'ne' }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  sendTo('mqtt.1', 'sendMessage2Client', { topic: 'W/c0619ab336ed/vebus/276/Mode', message: ('{"value":' + String(String(getState('0_userdata.0.Victron.ESS_Mode').val) + '}')), retain: false });
});
on({ id: [].concat(['0_userdata.0.Victron.BAT_Mode']), change: 'ne' }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  sendTo('mqtt.2', 'sendMessage2Client', { topic: 'W/c0619ab4bea6/vebus/276/Mode', message: ('{"value":' + String(String(getState('0_userdata.0.Victron.BAT_Mode').val) + '}')), retain: false });
});

// Mode - Change
on({ id: 'mqtt.1.N.c0619ab336ed.vebus.276.Mode' /* N/c0619ab336ed/vebus/276/Mode */, change: 'ne' }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  Berechnung = parseFloat(getAttr((() => { try { return JSON.parse((obj.state ? obj.state.val : '')); } catch (e) { return {}; }})(), 'value'));
  if (Berechnung != getState('0_userdata.0.Victron.ESS_Mode').val) {
    setState('0_userdata.0.Victron.ESS_Mode' /* ESS_Mode */, Berechnung);
  }
});
on({ id: 'mqtt.2.N.c0619ab4bea6.vebus.276.Mode' /* N/c0619ab4bea6/vebus/276/Mode */, change: 'ne' }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  Berechnung = parseFloat(getAttr((() => { try { return JSON.parse((obj.state ? obj.state.val : '')); } catch (e) { return {}; }})(), 'value'));
  if (Berechnung != getState('0_userdata.0.Victron.BAT_Mode').val) {
    setState('0_userdata.0.Victron.BAT_Mode' /* BAT_Mode */, Berechnung);
  }
});
// Nachtabschaltung - 4=OFF, 3=ON
schedule({ astro: 'sunset', shift: 0 }, async () => {
  if (getState('0_userdata.0.Victron.Abendabschaltung').val) {
    sendTo('mqtt.2', 'sendMessage2Client', { topic: 'W/c0619ab4bea6/vebus/276/Mode', message: '{"value":4}', retain: false });
    if (getState('0_userdata.0.Victron.DebugAktiv').val) {
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Victron BAT Multiplus wurden mit Sonnenuntergang ausgeschaltet.');
    }
    sendTo('telegram.0', 'send', {
      text: 'Victron BAT Multiplus wurden mit Sonnenuntergang ausgeschaltet.',
    });
    console.log('telegram: ' + 'Victron BAT Multiplus wurden mit Sonnenuntergang ausgeschaltet.');
  } else {
    if (getState('0_userdata.0.Victron.DebugAktiv').val) {
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Victron BAT Multiplus wurden nicht mit Sonnenuntergang ausgeschaltet.');
    }
  }
});
schedule({ astro: 'sunrise', shift: 0 }, async () => {
  if (getState('0_userdata.0.Victron.BAT_Mode').val != 3 && getState('0_userdata.0.Victron.Abendabschaltung').val) {
    sendTo('mqtt.2', 'sendMessage2Client', { topic: 'W/c0619ab4bea6/vebus/276/Mode', message: '{"value":3}', retain: false });
    if (getState('0_userdata.0.Victron.DebugAktiv').val) {
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Victron BAT Multiplus wurden mit Sonnenaufgang eingeschaltet.');
    }
    sendTo('telegram.0', 'send', {
      text: 'Victron BAT Multiplus wurden mit Sonnenaufgang eingeschaltet.',
    });
    console.log('telegram: ' + 'Victron BAT Multiplus wurden mit Sonnenaufgang eingeschaltet.');
  } else {
    if (getState('0_userdata.0.Victron.DebugAktiv').val) {
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Victron BAT Multiplus wurden nicht mit Sonnenaufgang eingeschaltet, dieser war aktiv.');
    }
  }
});


